-- Array elements (option_candidate_ids) have no native foreign key, so a
-- transcription or roster-drift problem would otherwise insert silently
-- and only surface later, against live data. Fail closed instead: abort
-- the whole migration if the seed doesn't fully resolve, rather than
-- leaving a partially-bad reference table live.
do $$
declare bad_rows integer;
begin
  select count(*) into bad_rows from ranked_private.daily_schedule;
  if bad_rows <> 220 then
    raise exception 'daily_schedule seed row count is %, expected 220', bad_rows;
  end if;
  select count(*) into bad_rows from ranked_private.daily_schedule ds
    where not exists(select 1 from ranked_private.players p where p.id = ds.player_id);
  if bad_rows <> 0 then
    raise exception 'daily_schedule has % row(s) whose player_id does not resolve in players', bad_rows;
  end if;
  select count(*) into bad_rows from ranked_private.daily_schedule ds
    where exists(select 1 from unnest(ds.option_candidate_ids) oc
      where not exists(select 1 from ranked_private.candidates c where c.id = oc));
  if bad_rows <> 0 then
    raise exception 'daily_schedule has % row(s) with an option_candidate_ids element that does not resolve in candidates', bad_rows;
  end if;
  select count(*) into bad_rows from ranked_private.daily_schedule ds
    where not (ds.player_id = any(ds.option_candidate_ids));
  if bad_rows <> 0 then
    raise exception 'daily_schedule has % row(s) whose correct player_id is missing from its own option_candidate_ids', bad_rows;
  end if;
end $$;

